"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { useFieldControl } from "@/components/ui/field"

type InputOTPProps = Omit<React.ComponentProps<"input">, "value" | "defaultValue" | "onChange" | "maxLength" | "type"> & {
  /** How many digits. */
  length?: number
  /** A separator stands after every this many slots (0 for none). Three and three for six. */
  group?: number
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** Called once, when the last slot fills. */
  onComplete?: (value: string) => void
  /** Pins a state for documentation ("focus"); set on the root. */
  "data-force"?: string
}

/**
 * One real input holds the code, so paste, autofill and the keyboard all work natively.
 * The slots only draw it. Whole, the lines ink in turn; wrong (aria-invalid), they turn crimson together.
 */
function InputOTP({
  length = 6,
  group = length % 2 === 0 ? length / 2 : length % 3 === 0 ? 3 : 0,
  value,
  defaultValue = "",
  onValueChange,
  onComplete,
  className,
  "data-force": force,
  onFocus,
  onBlur,
  onPointerUp,
  ...props
}: InputOTPProps) {
  const field = useFieldControl()
  const [own, setOwn] = React.useState(defaultValue)
  const [focused, setFocused] = React.useState(false)
  const code = (value ?? own).slice(0, length)
  const wrong = props["aria-invalid"] ?? field["aria-invalid"]
  const invalid = wrong === true || wrong === "true"
  const full = code.length === length
  const here = (focused || force?.includes("focus")) && !full ? code.length : -1

  const set = (raw: string) => {
    const next = raw.replace(/\D/g, "").slice(0, length)
    if (value === undefined) setOwn(next)
    onValueChange?.(next)
    if (next.length === length && next !== code) onComplete?.(next)
  }

  const slots: React.ReactNode[] = []
  for (let i = 0; i < length; i++) {
    if (i > 0 && group > 0 && i % group === 0) slots.push(<span key={`sep${i}`} className="db-code-sep" aria-hidden="true" />)
    slots.push(
      <span key={i} data-slot="input-otp-slot" className="db-code-slot" style={{ "--i": i } as React.CSSProperties} data-here={i === here ? "" : undefined} aria-hidden="true">
        {code[i] ? <span key={code[i]}>{code[i]}</span> : null}
      </span>
    )
  }

  return (
    <div data-slot="input-otp" data-force={force} data-state={full ? (invalid ? "wrong" : "done") : undefined} className={cn("db-code", className)}>
      <input
        inputMode="numeric"
        autoComplete="one-time-code"
        pattern={`[0-9]{${length}}`}
        {...props}
        id={props.id ?? field.id}
        aria-invalid={props["aria-invalid"] ?? field["aria-invalid"]}
        aria-describedby={props["aria-describedby"] ?? field["aria-describedby"]}
        value={code}
        onChange={(e) => set(e.target.value)}
        // A pasted code replaces what's there, so a full code fills every slot.
        onPaste={(e) => {
          e.preventDefault()
          set(e.clipboardData.getData("text"))
        }}
        onFocus={(e) => {
          setFocused(true)
          onFocus?.(e)
        }}
        onBlur={(e) => {
          setFocused(false)
          onBlur?.(e)
        }}
        // Always type at the end, so Backspace takes back the last digit.
        onPointerUp={(e) => {
          onPointerUp?.(e)
          e.currentTarget.setSelectionRange(code.length, code.length)
        }}
      />
      {slots}
    </div>
  )
}

export { InputOTP, type InputOTPProps }

@layer components {
  /* ── db-code ── a one-time code: digits drop onto short baselines, three and three */
  .db-code { position: relative; display: inline-flex; align-items: flex-end; gap: 0.18em; font-size: calc(var(--db-f) * var(--db-expression-scale)); }
  .db-field > .db-code { grid-column: 1 / -1; justify-self: start; margin-top: var(--db-space-2); }
  .db-code > input { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; padding: 0; border: 0; opacity: 0; font-size: 16px; cursor: text; }
  .db-code[data-force~="focus"], .db-code > input:focus-visible { outline: 0; } /* the waiting line is the focus mark */
  .db-code-slot {
    --c: var(--db-accent);
    display: grid; place-items: end center; width: 0.78em; height: 1.2em; padding-bottom: 0.1em;
    font-family: var(--db-expression); font-style: italic; line-height: 1; color: var(--db-ink); font-variant-numeric: lining-nums;
    background:
      linear-gradient(var(--c), var(--c)) no-repeat 50% 100% / 0% var(--db-stroke),
      linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0 100% / 100% var(--db-hairline);
    transition: background-size var(--db-moderato) var(--db-exhale);
  }
  .db-code-slot > span { animation: db-drop-in var(--db-moderato) var(--db-spiccato) backwards; }
  @keyframes db-drop-in { from { opacity: 0; translate: 0 -0.3em; } }
  .db-code-slot[data-here] { background-size: 100% var(--db-stroke), 100% var(--db-hairline); }
  .db-code-sep { align-self: center; width: var(--db-hairline); height: 0.7em; margin-inline: 0.12em; background: var(--db-rule-strong); rotate: 22deg; }
  .db-code-sep:is([dir="rtl"], [dir="rtl"] *) { rotate: -22deg; }
  /* Whole: the lines ink in turn. Wrong: they turn crimson together. */
  .db-code[data-state] .db-code-slot { background-size: 100% var(--db-stroke), 100% var(--db-hairline); transition-delay: calc(var(--i, 0) * 2 * var(--db-arpeggio)); }
  .db-code[data-state="done"] .db-code-slot { --c: var(--db-ink); }
  .db-code[data-state="wrong"] .db-code-slot { --c: var(--db-signal); color: var(--db-signal); transition-delay: 0s; }
}
